import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AppStatus, TranscriptionItem, VisualContent } from './types';
import { decode, decodeAudioData, createBlob } from './services/audioUtils';

const BASE_SYSTEM_INSTRUCTION = `
आप "उद्यमी सहेली" हैं, एक पेशेवर बिज़नेस कंसल्टेंट (सलाहकार)। 
आपका उद्देश्य ग्रामीण महिला उद्यमियों को बिज़नेस बढ़ाने में मदद करना है।

भाषा और लिपि नियम (अनिवार्य):
1. **सिर्फ हिंदी (देवनागरी लिपि)**: आपका हर शब्द और हर वाक्य केवल शुद्ध हिंदी और देवनागरी लिपि (Hindi Devanagari Script) में होना चाहिए। 
2. **अन्य लिपियों पर रोक**: उर्दू (Arabic/Persian script), पंजाबी (Gurmukhi script) या रोमन (English script) का प्रयोग बिलकुल न करें। यदि यूज़र किसी और भाषा में बोले, तब भी आप अपना जवाब केवल हिंदी देवनागरी में ही दें।
3. **सरलता**: भाषा "खड़ी बोली" जैसी सरल और आत्मीय रखें। "दीदी" या "बहन" कहकर बात करें।

कंसल्टेंट (सलाहकार) व्यवहार:
1. **डिस्कवरी (Discovery)**: किसी भी सलाह से पहले यूज़र के बिज़नेस को समझें। 
   - पहले पूछें: "नमस्ते दीदी! आप कहाँ से हैं और आपका बिज़नेस किस चीज़ का है?"
   - फिर पूछें: "क्या आपके पास पहले से कोई दुकान या काम है, या आप नया शुरू करना चाहती हैं?"
2. **सवाल पूछना**: सीधे जवाब देने के बजाय, पहले ज़रूरी सवाल पूछें (जैसे: बजट कितना है? बाज़ार कहाँ है?)।
3. **कस्टम सलाह**: यूज़र की जानकारी के आधार पर ही सलाह दें।

टूल्स का उपयोग:
- search_grounding: सरकारी योजनाएं, बैंक की जानकारी या बाज़ार की ताज़ा दरों के लिए।
- generate_image: पैकेजिंग डिज़ाइन या पोस्टर दिखाने के लिए।
`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और हिसाब', desc: 'लोन, बैंक और बजट की जानकारी', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बाज़ार और बिक्री', desc: 'ग्राहक ढूंढने और बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी योजनाएं', desc: 'SHG और सरकारी मदद की जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई और सवाल या बातचीत', icon: '💬' },
];

const searchGroundingTool: FunctionDeclaration = {
  name: 'search_grounding',
  parameters: {
    type: Type.OBJECT,
    properties: {
      query: { type: Type.STRING, description: 'सर्च करने के लिए सवाल (केवल हिंदी में)' },
      title: { type: Type.STRING, description: 'जानकारी का शीर्षक (केवल हिंदी में)' }
    },
    required: ['query', 'title']
  }
};

const generateImageTool: FunctionDeclaration = {
  name: 'generate_image',
  parameters: {
    type: Type.OBJECT,
    properties: {
      prompt: { type: Type.STRING, description: 'चित्र का विवरण (हिंदी में)' },
      isEditing: { type: Type.BOOLEAN, description: 'क्या पुराने चित्र को बदलना है?' },
      title: { type: Type.STRING, description: 'चित्र का नाम (हिंदी में)' }
    },
    required: ['prompt', 'title']
  }
};

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'DASHBOARD' | 'CHAT'>('WELCOME');
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const currentInputTranscription = useRef<string>('');
  const currentOutputTranscription = useRef<string>('');
  const currentToolVisual = useRef<VisualContent | null>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (view === 'CHAT') scrollToBottom();
  }, [messages, status, view]);

  const playTone = (type: 'start' | 'stop' | 'message') => {
    const ctx = audioContextRef.current?.output;
    if (!ctx) return;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'start') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now);
      osc.stop(now + 0.15);
    } else if (type === 'stop') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.exponentialRampToValueAtTime(440, now + 0.1);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now);
      osc.stop(now + 0.15);
    } else if (type === 'message') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(660, now);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    }
  };

  const stopAudio = () => {
    sourcesRef.current.forEach(s => {
      try { s.stop(); } catch (e) {}
    });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const handleBackToDashboard = () => {
    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch (e) {}
      sessionRef.current = null;
    }
    stopAudio();
    setView('DASHBOARD');
    setMessages([]);
    setSelectedTopic(null);
    setStatus(AppStatus.IDLE);
    if (isRecording) stopRecordingInternal();
  };

  const handleSelectTopic = (topic: typeof TOPICS[0]) => {
    setSelectedTopic(topic);
    setView('CHAT');
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) {
      micProcessorRef.current.disconnect();
      micProcessorRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
    setIsRecording(false);
  };

  const initSession = async (topic: typeof TOPICS[0]) => {
    if (sessionRef.current) return sessionRef.current;

    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const topicInstruction = topic.id === 'other' 
        ? "यूज़र किसी भी विषय पर बात कर सकता है।"
        : `यूज़र का मुख्य विषय "${topic.name}" है। सलाह इसी के इर्द-गिर्द रखें।`;

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: BASE_SYSTEM_INSTRUCTION + "\n" + topicInstruction,
        outputAudioTranscription: {},
        inputAudioTranscription: {},
        tools: [{ functionDeclarations: [searchGroundingTool, generateImageTool] }]
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.toolCall) {
            for (const fc of message.toolCall.functionCalls) {
              if (fc.name === 'search_grounding') {
                const args = fc.args as { query: string, title: string };
                await handleSearch(args.query, args.title);
                sessionRef.current?.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: "सर्च जानकारी मिल गई है।" } }]
                });
              } else if (fc.name === 'generate_image') {
                const args = fc.args as { prompt: string, title: string, isEditing: boolean };
                await handleImage(args.prompt, args.title, args.isEditing);
                sessionRef.current?.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: "चित्र तैयार है।" } }]
                });
              }
            }
          }

          if (message.serverContent?.inputTranscription) currentInputTranscription.current += message.serverContent.inputTranscription.text;
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;

          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            const visual = currentToolVisual.current;

            if (modelText || visual) {
              setMessages(prev => [
                ...prev,
                { text: modelText, role: 'model', timestamp: Date.now(), visual: visual || undefined } as TranscriptionItem
              ]);
              playTone('message');
            }
            currentInputTranscription.current = '';
            currentOutputTranscription.current = '';
            currentToolVisual.current = null;
          }

          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => {
              sourcesRef.current.delete(source);
              if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING);
            });
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
          }

          if (message.serverContent?.interrupted) {
            stopAudio();
          }
        },
        onerror: (e) => setError("नेटवर्क में दिक्कत आ रही है।"),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });

    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const handleSearch = async (query: string, title: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: query,
        config: { tools: [{ googleSearch: {} }] },
      });
      const links = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => ({
        uri: c.web?.uri || '',
        title: c.web?.title || 'जानकारी देखें'
      })).filter((l: any) => l.uri) || [];

      currentToolVisual.current = { type: 'search', title, content: response.text, groundingLinks: links };
      return "Success";
    } catch (e) { return "Error"; }
  };

  const handleImage = async (prompt: string, title: string, isEditing: boolean) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const parts: any[] = [{ text: prompt }];
      const response = await ai.models.generateContent({ model: 'gemini-2.5-flash-image', contents: { parts } });
      const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (part?.inlineData) {
        currentToolVisual.current = { type: 'image', title, url: `data:image/png;base64,${part.inlineData.data}`, content: response.text };
      }
      return "Success";
    } catch (e) { return "Error"; }
  };

  const toggleRecording = async () => {
    if (!isRecording) {
      if (!selectedTopic) return;
      stopAudio();
      const session = await initSession(selectedTopic);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const source = audioContextRef.current!.input.createMediaStreamSource(stream);
      const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(4096, 1, 1);
      scriptProcessor.onaudioprocess = (e) => {
        const pcmBlob = createBlob(e.inputBuffer.getChannelData(0));
        session?.sendRealtimeInput({ media: pcmBlob });
      };
      source.connect(scriptProcessor);
      scriptProcessor.connect(audioContextRef.current!.input.destination);
      micProcessorRef.current = scriptProcessor;
      setIsRecording(true);
      playTone('start');
    } else {
      stopRecordingInternal();
      playTone('stop');
    }
  };

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-orange-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-8 max-w-sm">
            {/* Animated Indian Woman Illustration */}
            <div className="relative w-64 h-64 animate-float">
                <div className="absolute inset-0 bg-orange-200/50 rounded-full blur-3xl"></div>
                <img 
                    src="https://img.freepik.com/free-vector/indian-woman-sari-wearing-glasses_23-2148216398.jpg?t=st=1740058000~exp=1740061600~hmac=62174620f5451e04192669e2c222e23d027f31526487e47a2485559c5d1e4c84&w=740" 
                    alt="Udyami Saheli" 
                    className="relative z-10 w-full h-full object-contain rounded-full border-4 border-white shadow-2xl"
                />
            </div>

            <div className="space-y-4">
              <h1 className="text-4xl font-black text-orange-900 devanagari tracking-tight">उद्यमी सहेली</h1>
              <p className="text-xl text-orange-700/80 font-bold devanagari">आपकी बिज़नेस पार्टनर</p>

              <div className="bg-white/80 backdrop-blur-sm p-5 rounded-3xl border border-orange-100 shadow-sm text-left space-y-3">
                <div className="flex items-start space-x-3">
                  <span className="text-orange-600 font-bold">●</span>
                  <p className="text-sm text-slate-700 devanagari">पैसा, बैंक लोन और सरकारी योजनाओं की जानकारी।</p>
                </div>
                <div className="flex items-start space-x-3">
                  <span className="text-orange-600 font-bold">●</span>
                  <p className="text-sm text-slate-700 devanagari">पैकेजिंग, मार्केटिंग और सामान बेचने के नए तरीके।</p>
                </div>
                <div className="flex items-start space-x-3">
                  <span className="text-orange-600 font-bold">●</span>
                  <p className="text-sm text-slate-700 devanagari">माइक बटन दबाकर बोलें और अपनी सहेली से सलाह लें।</p>
                </div>
              </div>
            </div>
          </div>

          <button 
            onClick={() => setView('DASHBOARD')}
            className="w-full max-w-xs bg-[#128c7e] hover:bg-[#075e54] text-white py-4 rounded-2xl font-bold text-xl devanagari shadow-xl shadow-green-900/20 flex items-center justify-center space-x-3 transition-all active:scale-95 group"
          >
            <span>शुरू करें</span>
            <svg className="w-6 h-6 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 7l5 5m0 0l-5 5m5-5H6" /></svg>
          </button>

          <p className="mt-4 text-[10px] text-slate-400 font-bold uppercase tracking-widest">Rural Enterprise Consultant v2.0</p>
        </div>
      ) : view === 'DASHBOARD' ? (
        <>
          <header className="bg-[#128c7e] text-white px-4 py-4 flex flex-col shadow-lg z-20">
            <div className="flex justify-between items-center mb-4">
              <h1 className="text-xl font-bold tracking-wide devanagari">उद्यमी सहेली</h1>
              <div className="flex space-x-4">
                  <svg className="w-5 h-5 opacity-80" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                  <svg className="w-5 h-5 opacity-80" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z" /></svg>
              </div>
            </div>
            <div className="flex justify-between px-2 text-[11px] font-bold uppercase tracking-widest border-b border-white/20 pb-2">
              <span className="opacity-60">चैट</span>
              <span className="border-b-2 border-white pb-2 px-4">बिज़नेस टॉपिक्स</span>
              <span className="opacity-60">मदद</span>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto bg-white">
            <div className="p-4 bg-orange-50/50 flex items-center space-x-4 border-b border-gray-100">
              <div className="w-12 h-12 bg-orange-600 rounded-full flex items-center justify-center text-white text-xl shadow-md overflow-hidden">
                <img src="https://img.freepik.com/free-vector/indian-woman-sari-wearing-glasses_23-2148216398.jpg" alt="Profile" className="w-full h-full object-cover" />
              </div>
              <div>
                 <h3 className="font-bold devanagari text-orange-900">आपकी बिज़नेस सहेली</h3>
                 <p className="text-[10px] text-orange-700/70 font-bold uppercase">कंसल्टेंट मोड एक्टिव</p>
              </div>
            </div>

            <div className="divide-y divide-gray-50">
              {TOPICS.map((topic) => (
                <button 
                  key={topic.id}
                  onClick={() => handleSelectTopic(topic)}
                  className="w-full flex items-center p-4 hover:bg-gray-50 active:bg-gray-100 transition-colors text-left group"
                >
                  <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center text-2xl group-hover:scale-110 transition-transform shadow-inner">
                    {topic.icon}
                  </div>
                  <div className="ml-4 flex-1 border-b border-gray-50 py-2">
                    <div className="flex justify-between items-baseline">
                      <h4 className="font-bold text-[16px] devanagari text-slate-800">{topic.name}</h4>
                      <span className="text-[10px] text-green-500 font-bold">● ऑनलाइन</span>
                    </div>
                    <p className="text-[12px] text-gray-500 devanagari mt-1 truncate">{topic.desc}</p>
                  </div>
                </button>
              ))}
            </div>
          </main>
        </>
      ) : (
        <div className="flex flex-col h-full whatsapp-bg">
          <header className="bg-[#128c7e] text-white px-4 py-3 flex items-center shadow-lg z-20">
            <div className="flex items-center space-x-2">
              <button onClick={handleBackToDashboard} className="p-1 hover:bg-black/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
              </button>
              <div className="w-10 h-10 rounded-full bg-slate-200 overflow-hidden border-2 border-white/20 shadow-md flex items-center justify-center">
                <span className="text-lg">{selectedTopic?.icon}</span>
              </div>
              <div className="flex flex-col">
                <h1 className="text-lg font-bold devanagari leading-none">{selectedTopic?.name}</h1>
                <p className="text-[10px] opacity-90 mt-1 uppercase tracking-tighter font-medium">
                  {status === AppStatus.SPEAKING ? 'सहेली बोल रही है...' : status === AppStatus.LISTENING ? 'सुन रही है...' : 'ऑनलाइन'}
                </p>
              </div>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto p-3 space-y-4 pb-28 scroll-smooth">
            <div className="flex justify-center my-4">
              <span className="bg-[#d1e4f2] text-[#4a5e6a] text-[10px] px-3 py-1 rounded-md font-bold uppercase shadow-sm">आज</span>
            </div>

            {messages.length === 0 && (
              <div className="flex justify-center items-center py-10 px-6 text-center">
                <div className="devanagari text-slate-500 text-sm bg-white/70 p-5 rounded-2xl shadow-sm border border-white/50 backdrop-blur-sm">
                  <p className="font-bold text-lg text-[#128c7e] mb-2">नमस्ते दीदी! 👋</p>
                  <p>मैं बिज़नेस सलाहकार हूँ। बातचीत शुरू करने के लिए माइक बटन दबाएं और बताएं कि आप कहाँ से हैं और क्या बिज़नेस करती हैं।</p>
                </div>
              </div>
            )}

            {messages.map((m, i) => (
              <div key={i} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                <div className={`max-w-[85%] p-3 rounded-lg relative ${m.role === 'user' ? 'bubble-user rounded-tr-none' : 'bubble-saheli rounded-tl-none'}`}>

                  {m.visual && (
                    <div className="mb-3 rounded-xl overflow-hidden bg-gray-50 border border-gray-100 shadow-md">
                      {m.visual.type === 'image' && m.visual.url && (
                        <img src={m.visual.url} className="w-full h-auto object-cover max-h-72" alt="visual" />
                      )}
                      {m.visual.type === 'search' && (
                        <div className="p-4 bg-blue-50/40">
                          <h4 className="font-bold text-sm text-blue-900 devanagari mb-3 flex items-center">
                            <span className="mr-2">🔍</span> {m.visual.title}
                          </h4>
                          <div className="space-y-2">
                            {m.visual.groundingLinks?.map((l, j) => (
                              <a 
                                key={j} href={l.uri} target="_blank" rel="noopener noreferrer"
                                className="text-[13px] text-blue-700 bg-white p-3 rounded-lg border border-blue-100 flex items-center justify-between hover:bg-blue-50 shadow-sm"
                              >
                                <span className="truncate flex-1 font-bold">{l.title}</span>
                                <svg className="w-4 h-4 ml-2 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                              </a>
                            ))}
                          </div>
                        </div>
                      )}
                      <div className="p-2 bg-white/90 border-t border-gray-100">
                        <h5 className="text-[11px] font-bold devanagari text-slate-700">{m.visual.title}</h5>
                      </div>
                    </div>
                  )}

                  <p className="devanagari text-[16px] leading-relaxed text-slate-800 pr-4 whitespace-pre-wrap">{m.text}</p>

                  <div className="flex items-center justify-end mt-1 space-x-1">
                    <span className="text-[9px] text-gray-400 font-bold">
                      {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                  </div>
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </main>

          <footer className="bg-[#f0f0f0] p-3 flex items-center space-x-3 z-30 shadow-[0_-2px_10px_rgba(0,0,0,0.05)]">
            <div className="flex-1 bg-white rounded-full px-5 py-3 shadow-sm flex items-center space-x-3 border border-gray-200">
              <span className="text-xl">😊</span>
              <div className="flex-1 devanagari text-[15px] font-medium truncate">
                {isRecording ? <span className="text-red-500 animate-pulse font-bold">सुन रही हूँ...</span> : <span className="text-gray-400">माइक दबाकर बात करें</span>}
              </div>
              <svg className="w-6 h-6 text-gray-400 rotate-45" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
            </div>

            <button
              onClick={toggleRecording}
              className={`w-14 h-14 rounded-full flex items-center justify-center text-white shadow-xl transition-all active:scale-90 ${isRecording ? 'mic-active bg-red-600' : 'bg-[#128c7e] hover:bg-[#075e54]'}`}
            >
              {isRecording ? (
                <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z" /></svg>
              ) : (
                <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/></svg>
              )}
            </button>
          </footer>
        </div>
      )}

      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/95 backdrop-blur-md z-50 flex flex-col items-center justify-center space-y-6">
          <div className="w-16 h-16 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin"></div>
          <div className="text-center">
            <h2 className="devanagari text-[#128c7e] text-2xl font-black mb-2">सहेली आ रही है...</h2>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Connecting Consultant</p>
          </div>
        </div>
      )}

      {error && (
        <div className="absolute top-24 left-6 right-6 bg-red-600 text-white p-4 rounded-2xl text-sm devanagari text-center shadow-2xl z-50">
          {error}
          <button onClick={() => setError(null)} className="block w-full mt-3 font-black underline uppercase text-[10px] tracking-widest opacity-80">Close</button>
        </div>
      )}

      <style>{`
        @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }

        @keyframes float {
          0% { transform: translateY(0px); }
          50% { transform: translateY(-15px); }
          100% { transform: translateY(0px); }
        }
        .animate-float { animation: float 5s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default App;

{
  "name": "Udyog Saheli - Business Consultant for Rural Women",
  "description": "A conversational voice agent in Hindi designed to help rural women entrepreneurs manage and grow their small businesses.",
  "requestFramePermissions": [
    "microphone",
    "camera"
  ]
}

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AppStatus, TranscriptionItem, VisualContent } from './types';
import { decode, decodeAudioData, createBlob } from './services/audioUtils';

const BASE_SYSTEM_INSTRUCTION = `
आप "उद्योग सहेली" हैं, एक पेशेवर बिज़नेस कंसल्टेंट (सलाहकार)। 
आपका उद्देश्य ग्रामीण महिला उद्यमियों को बिज़नेस बढ़ाने में मदद करना है।

भाषा और लिपि नियम (अनिवार्य):
1. **सिर्फ हिंदी (देवनागरी लिपि)**: आपका हर शब्द और हर वाक्य केवल शुद्ध हिंदी और देवनागरी लिपि (Hindi Devanagari Script) में होना चाहिए। 
2. **अन्य लिपियों पर रोक**: उर्दू (Arabic/Persian script), पंजाबी (Gurmukhi script) या रोमन (English script) का प्रयोग बिलकुल न करें। यदि यूज़र किसी और भाषा में बोले, तब भी आप अपना जवाब केवल हिंदी देवनागरी में ही दें।
3. **सरलता**: भाषा "खड़ी बोली" जैसी सरल और आत्मीय रखें। "दीदी" या "बहन" कहकर बात करें।

कंसल्टेंट (सलाहकार) व्यवहार:
1. **डिस्कवरी (Discovery)**: किसी भी सलाह से पहले यूज़र के बिज़नेस को समझें। 
   - पहले पूछें: "नमस्ते दीदी! आप कहाँ से हैं और आपका बिज़नेस किस चीज़ का है?"
   - फिर पूछें: "क्या आपके पास पहले से कोई दुकान या काम है, या आप नया शुरू करना चाहती हैं?"
2. **सवाल पूछना**: सीधे जवाब देने के बजाय, पहले ज़रूरी सवाल पूछें (जैसे: बजट कितना है? बाज़ार कहाँ है?)।
3. **कस्टम सलाह**: यूज़र की जानकारी के आधार पर ही सलाह दें।

टूल्स का उपयोग:
- search_grounding: सरकारी योजनाएं, बैंक की जानकारी या बाज़ार की ताज़ा दरों के लिए।
- generate_image: पैकेजिंग डिज़ाइन या पोस्टर दिखाने के लिए।
`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और हिसाब', desc: 'लोन, बैंक और बजट की जानकारी', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बाज़ार और बिक्री', desc: 'ग्राहक ढूंढने और बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी योजनाएं', desc: 'SHG और सरकारी मदद की जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई और सवाल या बातचीत', icon: '💬' },
];

const SAHELI_IMAGE = "https://img.freepik.com/free-vector/hand-drawn-traditional-indian-woman-illustration_23-2149187122.jpg?t=st=1740059000~exp=1740062600~hmac=e2c222e23d027f31526487e47a2485559c5d1e4c84&w=740";

const searchGroundingTool: FunctionDeclaration = {
  name: 'search_grounding',
  parameters: {
    type: Type.OBJECT,
    properties: {
      query: { type: Type.STRING, description: 'सर्च करने के लिए सवाल (केवल हिंदी में)' },
      title: { type: Type.STRING, description: 'जानकारी का शीर्षक (केवल हिंदी में)' }
    },
    required: ['query', 'title']
  }
};

const generateImageTool: FunctionDeclaration = {
  name: 'generate_image',
  parameters: {
    type: Type.OBJECT,
    properties: {
      prompt: { type: Type.STRING, description: 'चित्र का विवरण (हिंदी में)' },
      isEditing: { type: Type.BOOLEAN, description: 'क्या पुराने चित्र को बदलना है?' },
      title: { type: Type.STRING, description: 'चित्र का नाम (हिंदी में)' }
    },
    required: ['prompt', 'title']
  }
};

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'DASHBOARD' | 'CHAT'>('WELCOME');
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const currentInputTranscription = useRef<string>('');
  const currentOutputTranscription = useRef<string>('');
  const currentToolVisual = useRef<VisualContent | null>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (view === 'CHAT') scrollToBottom();
  }, [messages, status, view]);

  const playTone = (type: 'start' | 'stop' | 'message') => {
    const ctx = audioContextRef.current?.output;
    if (!ctx) return;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'start') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now);
      osc.stop(now + 0.15);
    } else if (type === 'stop') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.exponentialRampToValueAtTime(440, now + 0.1);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now);
      osc.stop(now + 0.15);
    } else if (type === 'message') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(660, now);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    }
  };

  const stopAudio = () => {
    sourcesRef.current.forEach(s => {
      try { s.stop(); } catch (e) {}
    });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const handleBackToDashboard = () => {
    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch (e) {}
      sessionRef.current = null;
    }
    stopAudio();
    setView('DASHBOARD');
    setMessages([]);
    setSelectedTopic(null);
    setStatus(AppStatus.IDLE);
    if (isRecording) stopRecordingInternal();
  };

  const handleSelectTopic = (topic: typeof TOPICS[0]) => {
    setSelectedTopic(topic);
    setView('CHAT');
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) {
      micProcessorRef.current.disconnect();
      micProcessorRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
    setIsRecording(false);
  };

  const initSession = async (topic: typeof TOPICS[0]) => {
    if (sessionRef.current) return sessionRef.current;

    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const topicInstruction = topic.id === 'other' 
        ? "यूज़र किसी भी विषय पर बात कर सकता है।"
        : `यूज़र का मुख्य विषय "${topic.name}" है। सलाह इसी के इर्द-गिर्द रखें।`;

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: BASE_SYSTEM_INSTRUCTION + "\n" + topicInstruction,
        outputAudioTranscription: {},
        inputAudioTranscription: {},
        tools: [{ functionDeclarations: [searchGroundingTool, generateImageTool] }]
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.toolCall) {
            for (const fc of message.toolCall.functionCalls) {
              if (fc.name === 'search_grounding') {
                const args = fc.args as { query: string, title: string };
                await handleSearch(args.query, args.title);
                sessionRef.current?.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: "सर्च जानकारी मिल गई है।" } }]
                });
              } else if (fc.name === 'generate_image') {
                const args = fc.args as { prompt: string, title: string, isEditing: boolean };
                await handleImage(args.prompt, args.title, args.isEditing);
                sessionRef.current?.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: "चित्र तैयार है।" } }]
                });
              }
            }
          }

          if (message.serverContent?.inputTranscription) currentInputTranscription.current += message.serverContent.inputTranscription.text;
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;

          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            const visual = currentToolVisual.current;

            if (modelText || visual) {
              setMessages(prev => [
                ...prev,
                { text: modelText, role: 'model', timestamp: Date.now(), visual: visual || undefined } as TranscriptionItem
              ]);
              playTone('message');
            }
            currentInputTranscription.current = '';
            currentOutputTranscription.current = '';
            currentToolVisual.current = null;
          }

          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => {
              sourcesRef.current.delete(source);
              if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING);
            });
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
          }

          if (message.serverContent?.interrupted) {
            stopAudio();
          }
        },
        onerror: (e) => setError("नेटवर्क में दिक्कत आ रही है।"),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });

    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const handleSearch = async (query: string, title: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: query,
        config: { tools: [{ googleSearch: {} }] },
      });
      const links = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => ({
        uri: c.web?.uri || '',
        title: c.web?.title || 'जानकारी देखें'
      })).filter((l: any) => l.uri) || [];

      currentToolVisual.current = { type: 'search', title, content: response.text, groundingLinks: links };
      return "Success";
    } catch (e) { return "Error"; }
  };

  const handleImage = async (prompt: string, title: string, isEditing: boolean) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const parts: any[] = [{ text: prompt }];
      const response = await ai.models.generateContent({ model: 'gemini-2.5-flash-image', contents: { parts } });
      const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (part?.inlineData) {
        currentToolVisual.current = { type: 'image', title, url: `data:image/png;base64,${part.inlineData.data}`, content: response.text };
      }
      return "Success";
    } catch (e) { return "Error"; }
  };

  const toggleRecording = async () => {
    if (!isRecording) {
      if (!selectedTopic) return;
      stopAudio();
      const session = await initSession(selectedTopic);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const source = audioContextRef.current!.input.createMediaStreamSource(stream);
      const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(4096, 1, 1);
      scriptProcessor.onaudioprocess = (e) => {
        const pcmBlob = createBlob(e.inputBuffer.getChannelData(0));
        session?.sendRealtimeInput({ media: pcmBlob });
      };
      source.connect(scriptProcessor);
      scriptProcessor.connect(audioContextRef.current!.input.destination);
      micProcessorRef.current = scriptProcessor;
      setIsRecording(true);
      playTone('start');
    } else {
      stopRecordingInternal();
      playTone('stop');
    }
  };

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-emerald-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-8 max-w-sm">
            {/* Animated Indian Woman Illustration representing a business owner */}
            <div className="relative w-64 h-64 animate-float">
                <div className="absolute inset-0 bg-emerald-200/50 rounded-full blur-3xl"></div>
                <img 
                    src={SAHELI_IMAGE} 
                    alt="Udyog Saheli" 
                    className="relative z-10 w-full h-full object-cover rounded-full border-4 border-white shadow-2xl"
                />
            </div>

            <div className="space-y-4">
              <h1 className="text-4xl font-black text-emerald-900 devanagari tracking-tight">उद्योग सहेली</h1>
              <p className="text-xl text-emerald-700/80 font-bold devanagari">आपकी बिज़नेस पार्टनर</p>

