const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'DASHBOARD' | 'CHAT'>('WELCOME');
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const currentInputTranscription = useRef<string>('');
  const currentOutputTranscription = useRef<string>('');
  const currentToolVisual = useRef<VisualContent | null>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (view === 'CHAT') scrollToBottom();
  }, [messages, status, view]);

  const playTone = (type: 'start' | 'stop' | 'message') => {
    const ctx = audioContextRef.current?.output;
    if (!ctx) return;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'start') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now);
      osc.stop(now + 0.15);
    } else if (type === 'stop') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.exponentialRampToValueAtTime(440, now + 0.1);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now);
      osc.stop(now + 0.15);
    } else if (type === 'message') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(660, now);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    }
  };

  const stopAudio = () => {
    sourcesRef.current.forEach(s => {
      try { s.stop(); } catch (e) {}
    });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const handleBackToDashboard = () => {
    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch (e) {}
      sessionRef.current = null;
    }
    stopAudio();
    setView('DASHBOARD');
    setMessages([]);
    setSelectedTopic(null);
    setStatus(AppStatus.IDLE);
    if (isRecording) stopRecordingInternal();
  };

  const handleSelectTopic = (topic: typeof TOPICS[0]) => {
    setSelectedTopic(topic);
    setView('CHAT');
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) {
      micProcessorRef.current.disconnect();
      micProcessorRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
    setIsRecording(false);
  };

  const initSession = async (topic: typeof TOPICS[0]) => {
    if (sessionRef.current) return sessionRef.current;

    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const topicInstruction = topic.id === 'other' 
        ? "यूज़र किसी भी विषय पर बात कर सकता है।"
        : `यूज़र का मुख्य विषय "${topic.name}" है। सलाह इसी के इर्द-गिर्द रखें।`;

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: BASE_SYSTEM_INSTRUCTION + "\n" + topicInstruction,
        outputAudioTranscription: {},
        inputAudioTranscription: {},
        tools: [{ functionDeclarations: [searchGroundingTool, generateImageTool] }]
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.toolCall) {
            for (const fc of message.toolCall.functionCalls) {
              if (fc.name === 'search_grounding') {
                const args = fc.args as { query: string, title: string };
                await handleSearch(args.query, args.title);
                sessionRef.current?.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: "सर्च जानकारी मिल गई है।" } }]
                });
              } else if (fc.name === 'generate_image') {
                const args = fc.args as { prompt: string, title: string, isEditing: boolean };
                await handleImage(args.prompt, args.title, args.isEditing);
                sessionRef.current?.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: "चित्र तैयार है।" } }]
                });
              }
            }
          }

          if (message.serverContent?.inputTranscription) currentInputTranscription.current += message.serverContent.inputTranscription.text;
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;

          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            const visual = currentToolVisual.current;

            if (modelText || visual) {
              setMessages(prev => [
                ...prev,
                { text: modelText, role: 'model', timestamp: Date.now(), visual: visual || undefined } as TranscriptionItem
              ]);
              playTone('message');
            }
            currentInputTranscription.current = '';
            currentOutputTranscription.current = '';
            currentToolVisual.current = null;
          }

          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => {
              sourcesRef.current.delete(source);
              if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING);
            });
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
          }

          if (message.serverContent?.interrupted) {
            stopAudio();
          }
        },
        onerror: (e) => setError("नेटवर्क में दिक्कत आ रही है।"),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });

    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const handleSearch = async (query: string, title: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: query,
        config: { tools: [{ googleSearch: {} }] },
      });
      const links = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => ({
        uri: c.web?.uri || '',
        title: c.web?.title || 'जानकारी देखें'
      })).filter((l: any) => l.uri) || [];

      currentToolVisual.current = { type: 'search', title, content: response.text, groundingLinks: links };
      return "Success";
    } catch (e) { return "Error"; }
  };

  const handleImage = async (prompt: string, title: string, isEditing: boolean) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const parts: any[] = [{ text: prompt }];
      const response = await ai.models.generateContent({ model: 'gemini-2.5-flash-image', contents: { parts } });
      const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (part?.inlineData) {
        currentToolVisual.current = { type: 'image', title, url: `data:image/png;base64,${part.inlineData.data}`, content: response.text };
      }
      return "Success";
    } catch (e) { return "Error"; }
  };

  const toggleRecording = async () => {
